            S = {v}
            U = uncolored - {v} - neighbors[v]
            W = set(uncolored) - U - S
            while U:
                best_u = -1
                max_nw = -1
                min_deg_u = float('inf')
                for u in U:
                    nw = sum(1 for w in neighbors[u] if w in W)
                    if nw > max_nw:
                        max_nw = nw
                        best_u = u
                        min_deg_u = sum(1 for w in neighbors[u] if w in U)
                    elif nw == max_nw:
                        deg_u = sum(1 for w in neighbors[u] if w in U)
                        if deg_u < min_deg_u:
                            min_deg_u = deg_u
                            best_u = u
                        elif deg_u == min_deg_u:
                            if random.random() < 0.5:
                                best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            for u in S:
                color[u] = c
            uncolored -= S
            c += 1
        return color

    # Heuristic 4: Greedy with degree ordering (Welsh-Powell)
    def greedy_degree():
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        color = [-1] * n
        for v in order:
            used = {color[u] for u in neighbors[v] if color[u] != -1}
            c = 0
            while c in used:
                c += 1
            color[v] = c
        return color

    # Heuristic 5: Randomized greedy with shuffling
    def randomized_greedy():
        order = list(range(n))
        random.shuffle(order)
        color = [-1] * n
        for v in order:
            used = {color[u] for u in neighbors[v] if color[u] != -1}
            c = 0
            while c in used:
                c += 1
            color[v] = c
        return color

    # Heuristic 6: Iterative DSATUR with restarts
    def dsatur_iterative():
        best_col = None
        best_k = float('inf')
        for _ in range(5):  # Limited restarts for speed
            color = [-1] * n
            sat = [0] * n
            neighbor_colors = [set() for _ in range(n)]
            uncolored = set(range(n))
            while uncolored:
                v = -1
                max_sat = -1
                max_deg = -1
                for u in uncolored:
                    if sat[u] > max_sat:
                        max_sat = sat[u]
                        max_deg = len([w for w in neighbors[u] if w in uncolored])
                        v = u
                    elif sat[u] == max_sat:
                        deg_u = len([w for w in neighbors[u] if w in uncolored])
                        if deg_u > max_deg:
                            max_deg = deg_u
                            v = u
                        elif deg_u == max_deg:
                            if random.random() < 0.5:
                                v = u
                used = neighbor_colors[v]
                c = 0
                while c in used:
                    c += 1
                color[v] = c
                uncolored.remove(v)
                for u in neighbors[v]:
                    if u in uncolored:
                        if c not in neighbor_colors[u]:
                            neighbor_colors[u].add(c)
                            sat[u] += 1
            k = max(color) + 1 if n > 0 else 0
            if k < best_k:
                best_k = k
                best_col = color[:]
        return best_col if best_col is not None else greedy_degree()

    # Kempe chain color class elimination
    def kempe_reduce(color_in):
        color = color_in[:]
        k = max(color) + 1 if n > 0 else 0
        if k <= 1:
            return color
        improved = True
        while improved and k > 1:
            improved = False
            target = k - 1
            vertices_target = [v for v in range(n) if color[v] == target]
            if not vertices_target:
                k -= 1
                improved = True
                continue
            cur_color = color[:]
            made_change = False
            for v in vertices_target:
                if cur_color[v] != target:
                    continue
                for c in range(target):
                    if any(cur_color[u] == c for u in neighbors[v]):
                        continue
                    cur_color[v] = c
                    made_change = True
                    break
                else:
                    for c in range(target):
                        comp = set()
                        stack = [v]
                        comp.add(v)
                        while stack:
                            x = stack.pop()
                            for y in neighbors[x]:
                                if y in comp:
                                    continue
                                if cur_color[y] == c or cur_color[y] == target:
                                    comp.add(y)
                                    stack.append(y)
                        conflict = False
                        for u in neighbors[v]:
                            if u in comp and u != v and cur_color[u] == target:
                                conflict = True
                                break
                        if not conflict:
                            for x in comp:
                                if cur_color[x] == c:
                                    cur_color[x] = target
                                elif cur_color[x] == target:
                                    cur_color[x] = c
                            made_change = True
                            break
                    if made_change:
                        break
            if made_change:
                new_target = [v for v in range(n) if cur_color[v] == target]
                if len(new_target) < len(vertices_target):
                    color = cur_color
                    improved = True
                    if not new_target:
                        k -= 1
            else:
                break
        return color

    # Main: try multiple heuristics and keep the best
    heuristics = [
        smallest_last,
        dsatur_adaptive,
        rlf_optimized,
        greedy_degree,
        randomized_greedy,
        dsatur_iterative
    ]
    best_color = None
    best_k = float('inf')
    for func in heuristics:
        try:
            col = func()
            k = max(col) + 1 if n > 0 else 0
            if k < best_k:
                best_color = col
                best_k = k
            elif k == best_k and best_color is not None:
                zeros_cur = sum(1 for c in col if c == 0)
                zeros_best = sum(1 for c in best_color if c == 0)
                if zeros_cur > zeros_best:
                    best_color = col
        except Exception:
            continue
    if best_color is not None:
        improved = kempe_reduce(best_color)
        k_improved = max(improved) + 1 if n > 0 else 0
        if k_improved < best_k:
            best_color = improved
    return best_color if best_color is not None else [0] * n
